def roman(s):
    s = s.strip()
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    for char in s:
        if char in roman_dict:
            result += roman_dict[char]
        else:
            return 0
    return result
