def balanced(s):
    stack = []
    for i in s:
        if i in "([{":
            stack.append(i)
        elif i in ")]}":
            if not stack or (stack[-1] == '(' and i != ')') or (stack[-1] == '[' and i != ']') or (stack[-1] == '{' and i != '}'):
                return False
            stack.append(i)
    return not stack
```

```python
def rle(s):
    if not s:
        return ""
    res = []
    for char in s:
        if not res or res[-1][0] != char:
            res.append([char, 1])
        else:
            res[-1][1] += 1
    return ''.join([f'{char}{res[-1][1]}' if res[-1][1] != 1 else f'{char}' for char in res])
```

